package cn.zhuatech.iam.deep;import cn.zhuatech.iam.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.time.*;@RestController@RequestMapping("/api/admin/iam-ops")public class DeepAdminController{private final DeepDomainService s;public DeepAdminController(DeepDomainService s){this.s=s;}@PostMapping("/tenants")ApiResponse<?>tenant(@Valid@RequestBody DeepDomainService.TenantRequest r){return ApiResponse.ok(s.tenant(r));}@PostMapping("/tenants/{id}/activate")ApiResponse<?>activate(@PathVariable Long id){return ApiResponse.ok(s.activateTenant(id));}@PostMapping("/tenants/{id}/roles")ApiResponse<?>role(@PathVariable Long id,@Valid@RequestBody DeepDomainService.RoleRequest r){return ApiResponse.ok(s.role(id,r));}@PostMapping("/access-requests/{id}/review")ApiResponse<?>review(@PathVariable Long id,@Valid@RequestBody DeepDomainService.ReviewRequest r){return ApiResponse.ok(s.review(id,r));}@PostMapping("/assignments/{id}/revoke")ApiResponse<?>revoke(@PathVariable Long id,@Valid@RequestBody DeepDomainService.RevokeRequest r){return ApiResponse.ok(s.revoke(id,r));}@PostMapping("/assignments/expire")ApiResponse<?>expire(@RequestParam LocalDate asOf){return ApiResponse.ok(s.expire(asOf));}}
